<script setup lang="ts">
import { formatTanggalWib, tanggalHariIniWib } from '~~/shared/utils/waktu'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '~/components/ui/card'
import { NativeSelect, NativeSelectOption } from '~/components/ui/native-select'
import { Button } from '~/components/ui/button'
import { Checkbox } from '~/components/ui/checkbox'
import { Input } from '~/components/ui/input'
import { Badge } from '~/components/ui/badge'
import { Skeleton } from '~/components/ui/skeleton'
definePageMeta({ layout: 'dashboard', title: 'Laporan kegiatan PIMPASA' })
const route = useRoute()
const hariIni = tanggalHariIniWib()
const halaman = ref(1), kantorId = ref(typeof route.query.kantorId === 'string' ? route.query.kantorId : '')
const filter = reactive({ hanyaDiganti: false, dari: `${hariIni.slice(0, 7)}-01`, sampai: hariIni, desaId: '', jenisId: '', pegawaiId: '' })
const { data, pending, error, refresh } = await useDaftarKegiatanKanwil(halaman, kantorId, filter)
const totalHalaman = computed(() => Math.max(1, Math.ceil(data.value.total / 20)))
watch(filter, () => { halaman.value = 1 }, { deep: true })
watch(kantorId, () => { halaman.value = 1 })
</script>
<template>
<div class="grid gap-5">
  <header class="flex flex-wrap items-end justify-between gap-4"><div><h2 class="text-2xl font-semibold tracking-tight">Kegiatan PIMPASA</h2><p class="mt-1 text-sm text-muted-foreground">Laporan kegiatan DBI lintas UPT. Halaman ini hanya-baca untuk Kanwil dan admin.</p></div><Button variant="outline" @click="refresh()">Muat ulang</Button></header>
  <Card><CardHeader><CardTitle>Filter kegiatan</CardTitle><CardDescription>Tanggal kegiatan, UPT, desa, jenis, dan petugas.</CardDescription></CardHeader><CardContent class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><label class="grid gap-1.5 text-sm font-medium">UPT<NativeSelect v-model="kantorId"><NativeSelectOption value="">Semua UPT</NativeSelectOption><NativeSelectOption v-for="item in data.kantor" :key="item.id" :value="item.id">{{ item.nama_singkat }}</NativeSelectOption></NativeSelect></label><label class="grid gap-1.5 text-sm font-medium">Dari tanggal<Input v-model="filter.dari" type="date" :max="filter.sampai" /></label><label class="grid gap-1.5 text-sm font-medium">Sampai tanggal<Input v-model="filter.sampai" type="date" :min="filter.dari" :max="hariIni" /></label><label class="grid gap-1.5 text-sm font-medium">Desa<NativeSelect v-model="filter.desaId"><NativeSelectOption value="">Semua desa</NativeSelectOption><NativeSelectOption v-for="item in data.pilihan.desa" :key="item.id" :value="item.id">{{ item.nama }}</NativeSelectOption></NativeSelect></label><label class="grid gap-1.5 text-sm font-medium">Jenis kegiatan<NativeSelect v-model="filter.jenisId"><NativeSelectOption value="">Semua jenis</NativeSelectOption><NativeSelectOption v-for="item in data.pilihan.jenis" :key="item.id" :value="item.id">{{ item.nama }}</NativeSelectOption></NativeSelect></label><label class="grid gap-1.5 text-sm font-medium">Petugas<NativeSelect v-model="filter.pegawaiId"><NativeSelectOption value="">Semua petugas</NativeSelectOption><NativeSelectOption v-for="item in data.pilihan.pegawai" :key="item.id" :value="item.id">{{ item.nama }}</NativeSelectOption></NativeSelect></label><label class="flex items-center gap-2 self-end text-sm"><Checkbox v-model="filter.hanyaDiganti" />Petugas pengganti saja</label><Button class="w-fit self-end" variant="outline" @click="Object.assign(filter, { hanyaDiganti: false, dari: '', sampai: '', desaId: '', jenisId: '', pegawaiId: '' }); kantorId = ''">Reset filter</Button></CardContent></Card>
  <Card><CardHeader><CardTitle>Riwayat kegiatan</CardTitle><CardDescription>{{ data.total }} kegiatan · urutan terbaru</CardDescription></CardHeader><CardContent><div v-if="pending" class="grid gap-3"><Skeleton v-for="i in 6" :key="i" class="h-12 w-full" /></div><div v-else-if="error" class="grid gap-3 text-sm text-destructive" role="alert">Daftar kegiatan belum dapat dimuat.<Button class="w-fit" variant="outline" @click="refresh()">Coba lagi</Button></div><template v-else><div class="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Tanggal</TableHead><TableHead>UPT</TableHead><TableHead>Desa</TableHead><TableHead>Petugas</TableHead><TableHead>Jenis kegiatan</TableHead><TableHead>Peserta</TableHead><TableHead>Penugasan</TableHead><TableHead>Lampiran</TableHead><TableHead>Aksi</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in data.data" :key="item.id"><TableCell>{{ formatTanggalWib(item.tanggal_kegiatan) }}</TableCell><TableCell>{{ item.kantor }}</TableCell><TableCell>{{ item.desa }}</TableCell><TableCell>{{ item.pegawai }}</TableCell><TableCell>{{ item.jenis }}</TableCell><TableCell>{{ item.jumlah_peserta }}</TableCell><TableCell><Badge v-if="item.petugas_pengganti" variant="secondary">Digantikan</Badge><span v-else>Reguler</span></TableCell><TableCell><span v-if="item.ada_foto">Foto </span><span v-if="item.ada_pdf">PDF</span><span v-if="!item.ada_foto && !item.ada_pdf" class="text-muted-foreground">—</span></TableCell><TableCell><NuxtLink class="font-medium underline-offset-4 hover:underline" :to="`/kanwil/kegiatan/${item.id}`">Detail</NuxtLink></TableCell></TableRow><TableEmpty v-if="!data.data.length" :colspan="9">Belum ada laporan kegiatan pada rentang terpilih.</TableEmpty></TableBody></Table></div><nav class="mt-4 flex items-center justify-between"><Button variant="outline" :disabled="halaman <= 1" @click="halaman--">Sebelumnya</Button><span class="text-sm text-muted-foreground">Halaman {{ halaman }} dari {{ totalHalaman }}</span><Button variant="outline" :disabled="halaman >= totalHalaman" @click="halaman++">Berikutnya</Button></nav></template></CardContent></Card></div>
</template>
